import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Uses Gemini to generate a high-quality music prompt based on user description
 */
export async function generateMusicPrompt(userDescription: string) {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Act as a world-class prompt engineer for Suno and Udio. 
    Convert this user idea into a structured music style prompt and a lyrics/structure draft.
    User Idea: "${userDescription}"

    Respond in JSON format with "style" and "structure" fields.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          style: { type: Type.STRING },
          structure: { type: Type.STRING }
        },
        required: ["style", "structure"]
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (e) {
    return { style: response.text, structure: "Error parsing structure" };
  }
}

/**
 * Transcribes audio using Gemini 3 Flash Preview
 */
export async function transcribeAudio(base64Audio: string) {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'audio/pcm;rate=16000',
            data: base64Audio,
          },
        },
        { text: "Transcribe the following audio precisely. If there are lyrics, provide them. If it is a musical description, transcribe the spoken words." }
      ]
    }
  });

  return response.text;
}

/**
 * AI Audio Mastering Analysis
 */
export async function analyzeTrackForMastering(trackTitle: string, genre: string) {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze a music track titled "${trackTitle}" in the "${genre}" genre. 
    Provide 3 professional mastering tips to make it sound industry-standard.
    Return a list of suggestions.`,
  });

  return response.text;
}

import React, { useState } from 'react';
import { AppView } from './types';
import LandingPage from './components/LandingPage';
import Catalog from './components/Catalog';
import Studio from './components/Studio';
import Mastering from './components/Mastering';
import SunoArchitect from './components/SunoArchitect';
import Sidebar from './components/Sidebar';
import Header from './components/Header';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('landing');

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onEnter={() => setView('catalog')} />;
      case 'catalog': return <Catalog onOpenStudio={() => setView('studio')} />;
      case 'studio': return <Studio />;
      case 'mastering': return <Mastering />;
      case 'suno': return <SunoArchitect />;
      default: return <LandingPage onEnter={() => setView('catalog')} />;
    }
  };

  if (view === 'landing') {
    return <LandingPage onEnter={() => setView('catalog')} />;
