import React, { useState, useRef } from 'react';
import { transcribeAudio } from '../services/geminiService';

const Studio: React.FC = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [transcription, setTranscription] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [trackTitle, setTrackTitle] = useState("New Session #471");
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = async () => {
        setIsProcessing(true);
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = async () => {
          const base64Audio = (reader.result as string).split(',')[1];
          try {
            const text = await transcribeAudio(base64Audio);
            setTranscription(text);
          } catch (e) {
            setTranscription("Error transcribing audio. Ensure API key is valid.");
          }
          setIsProcessing(false);
        };
      };

      recorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Error accessing mic", err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto">
      <div className="bg-slate-900 border border-slate-800 rounded-[2.5rem] p-8 md:p-12 flex flex-col lg:flex-row items-center gap-12 shadow-2xl relative overflow-hidden">
        {/* Background glow */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 blur-[100px] -z-0"></div>

        <div className="w-full lg:w-1/3 flex flex-col items-center">
          <div className="relative group cursor-pointer mb-6">
            <div className={`w-48 h-48 rounded-full bg-slate-800 border-4 ${isRecording ? 'border-rose-500 animate-pulse' : 'border-slate-700'} flex items-center justify-center overflow-hidden relative shadow-2xl`}>
               <svg className={`w-16 h-16 ${isRecording ? 'text-rose-500' : 'text-slate-600'}`} fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
               {isRecording && <div className="absolute inset-0 bg-rose-500/10"></div>}
            </div>
            <button 
              onClick={isRecording ? stopRecording : startRecording}
              className={`absolute -bottom-4 left-1/2 -translate-x-1/2 px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all ${isRecording ? 'bg-rose-600 text-white' : 'bg-white text-slate-900 hover:scale-105'}`}
            >
              {isRecording ? 'Stop Recording' : 'Voice Input'}
            </button>
          </div>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Input Gain: -12.4dB</p>
        </div>

        <div className="flex-1 space-y-6 w-full z-10">
          <div className="flex flex-col md:flex-row justify-between items-start gap-4">
            <div>
              <h3 className="text-3xl font-black text-white mb-1" contentEditable suppressContentEditableWarning onBlur={(e) => setTrackTitle(e.currentTarget.innerText)}>{trackTitle}</h3>
              <p className="text-indigo-400 font-mono text-sm uppercase font-bold tracking-tighter">AI Analysis Queue: <span className="text-emerald-500">Idle</span></p>
            </div>
            <div className="flex gap-2">
              <button className="p-3 bg-slate-800 border border-slate-700 rounded-xl hover:text-white transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg></button>
              <button className="p-3 bg-slate-800 border border-slate-700 rounded-xl hover:text-white transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"></path></svg></button>
            </div>
          </div>

          <div className="bg-slate-950/50 rounded-2xl p-6 border border-slate-800 min-h-[120px] relative overflow-hidden">
            <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest block mb-3">AI Transcription / Lyrics Draft</label>
            {isProcessing ? (
              <div className="flex items-center gap-3 text-indigo-400 font-medium italic animate-pulse">
                <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                Processing audio stream...
              </div>
            ) : transcription ? (
              <p className="text-slate-200 leading-relaxed font-medium">{transcription}</p>
            ) : (
              <p className="text-slate-600 italic">Record your voice to generate lyrics or provide creative direction through the microphone.</p>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
         {['Stems Extractor', 'Chord Detector', 'Vocal Cleaner', 'MIDI Exporter'].map(tool => (
           <div key={tool} className="bg-slate-900 border border-slate-800 p-6 rounded-2xl hover:border-slate-700 transition-all cursor-pointer group">
             <div className="w-10 h-10 rounded-lg bg-indigo-500/10 text-indigo-500 flex items-center justify-center mb-4 group-hover:bg-indigo-500 group-hover:text-white transition-all">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 4a2 2 0 114 0v1a2 2 0 11-4 0V4zM11 13a2 2 0 114 0v1a2 2 0 11-4 0v-1zM11 22a2 2 0 114 0v1a2 2 0 11-4 0v-1z"></path></svg>
             </div>
             <h4 className="font-bold text-slate-200">{tool}</h4>
             <p className="text-xs text-slate-500 mt-1">Advanced AI processing utility.</p>
           </div>
         ))}
      </div>
    </div>
  );
};

export default Studio;

import React, { useState } from 'react';
import { analyzeTrackForMastering } from '../services/geminiService';

const Mastering: React.FC = () => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [tips, setTips] = useState<string | null>(null);

  const runAnalysis = async () => {
    setIsAnalyzing(true);
    try {
      const res = await analyzeTrackForMastering("Cyber Folk Anthem", "Future Bass / Folk-Tech");
      setTips(res);
    } catch (e) {
      setTips("Could not generate mastering tips. Check API connection.");
    }
    setIsAnalyzing(false);
