import { GoogleGenAI, Type, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function generateMusicPrompt(userDescription: string) {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Act as a world-class prompt engineer for music AI. 
    Convert this idea into a structured style prompt and lyrics/structure.
    User Idea: "${userDescription}"
    Include BPM, specific instrumentation, and mood.
    Respond in JSON format with "style" and "structure" fields.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          style: { type: Type.STRING },
          structure: { type: Type.STRING }
        },
        required: ["style", "structure"]
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (e) {
    return { style: response.text, structure: "Error parsing structure" };
  }
}

export async function transcribeAudio(base64Audio: string) {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'audio/pcm;rate=16000',
            data: base64Audio,
          },
        },
        { text: "Transcribe the following audio precisely. If it's a song, provide lyrics. If it's instructions, provide a summary." }
      ]
    }
  });
  return response.text;
}

/**
 * Uses Gemini to analyze audio and detect chord progressions.
 */
export async function detectChords(base64Audio: string) {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'audio/pcm;rate=16000',
            data: base64Audio,
          },
        },
        { text: "Analyze this audio and identify the musical chord progression. Return a JSON array of strings representing the chords (e.g. ['Am', 'F', 'C', 'G']). Focus only on the most prominent chords." }
      ]
    },
    config: {
      responseMimeType: "application/json",
