                  className={`text-[10px] font-mono uppercase font-bold tracking-tighter px-3 py-1 rounded-full border transition-all ${activeAnalysisMode === 'chords' ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : 'bg-slate-800 border-slate-700 text-slate-500'}`}
                >
                  Chord Detection
                </button>
              </div>
            </div>
            <div className="text-right">
              <p className="text-indigo-400 font-mono text-sm uppercase font-bold tracking-tighter">AI Analysis Queue: <span className={isProcessing || isLiveActive ? "text-emerald-500" : "text-slate-600"}>{isProcessing ? "Processing..." : isLiveActive ? "Streaming" : "Idle"}</span></p>
            </div>
          </div>

          <div className="bg-slate-950/50 rounded-2xl p-6 border border-slate-800 min-h-[160px] relative overflow-hidden backdrop-blur-md">
            <label className="text-[10px] text-slate-500 font-black uppercase tracking-widest block mb-3">
              {activeAnalysisMode === 'transcribe' ? 'Studio Log & Drafts' : 'Detected Chord Progression'}
