              <div className={`w-10 h-10 rounded-lg flex items-center justify-center mb-4 transition-all ${tool.active ? 'bg-emerald-500 text-white' : 'bg-indigo-500/10 text-indigo-500 group-hover:bg-indigo-600 group-hover:text-white'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={tool.icon}></path></svg>
