              )
            ) : (
              <div className="flex flex-wrap gap-4">
                {detectedChordsList.length > 0 ? (
                  detectedChordsList.map((chord, idx) => (
                    <div key={idx} className="flex flex-col items-center">
                      <div className="w-16 h-20 bg-emerald-500/10 border border-emerald-500/30 rounded-xl flex items-center justify-center text-emerald-400 font-black text-xl shadow-lg shadow-emerald-500/5 hover:scale-105 transition-transform cursor-default">
