                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* FX Matrix Section */}
      <div className={`grid grid-cols-1 lg:grid-cols-3 gap-6 transition-all duration-1000 ${isAmbientMode ? 'opacity-20' : ''}`}>
        <div className="lg:col-span-2 bg-slate-900 border border-slate-800 rounded-[2.5rem] p-8 shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-indigo-500/20 text-indigo-400 rounded-xl flex items-center justify-center">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z"></path></svg>
              </div>
              <h4 className="text-xl font-black text-white uppercase tracking-tighter italic">FX <span className="text-indigo-500">Matrix</span></h4>
            </div>
            <div className="flex gap-2">
               <span className="px-3 py-1 bg-slate-950 border border-slate-800 rounded-full text-[9px] font-mono text-indigo-400 uppercase tracking-widest">Real-time DSP</span>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className={`p-5 rounded-2xl border transition-all ${fx.reverb.active ? 'bg-indigo-500/5 border-indigo-500/40' : 'bg-slate-950/40 border-slate-800'}`}>
              <div className="flex justify-between items-center mb-4">
                <h5 className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Aura Reverb</h5>
                <button onClick={() => toggleFx('reverb')} className={`w-8 h-4 rounded-full relative transition-colors ${fx.reverb.active ? 'bg-indigo-600' : 'bg-slate-800'}`}>
                  <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-all ${fx.reverb.active ? 'right-0.5' : 'left-0.5'}`}></div>
                </button>
              </div>
              <div className="space-y-4">
                <div>
                  <div className="flex justify-between text-[9px] text-slate-500 uppercase font-black mb-1"><span>Wet/Dry</span> <span>{Math.round(fx.reverb.mix * 100)}%</span></div>
                  <input type="range" min="0" max="1" step="0.01" value={fx.reverb.mix} onChange={(e) => updateFxParam('reverb', 'mix', parseFloat(e.target.value))} className="w-full accent-indigo-500 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer" />
                </div>
                <div>
                  <div className="flex justify-between text-[9px] text-slate-500 uppercase font-black mb-1"><span>Decay</span> <span>{fx.reverb.decay}s</span></div>
                  <input type="range" min="0.5" max="8" step="0.1" value={fx.reverb.decay} onChange={(e) => updateFxParam('reverb', 'decay', parseFloat(e.target.value))} className="w-full accent-indigo-500 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer" />
