            <button onClick={() => toggleFx('distortion')} className={`w-8 h-4 rounded-full relative transition-colors ${fx.distortion.active ? 'bg-rose-600' : 'bg-slate-800'}`}><div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-all ${fx.distortion.active ? 'right-0.5' : 'left-0.5'}`}></div></button>
