                ) : isLiveActive ? <div className="text-emerald-400/80 animate-pulse font-mono text-sm">> Listening... Ask me about your arrangement or mixing challenges.</div> : <p className="text-slate-600 italic">Record a session to generate lyrics, or start the Live Producer to get real-time musical advice.</p>}
              </div>
            ) : (
              <div className="flex flex-wrap gap-4">
