          {renderPresetSelector()}
        </div>
      );
    }
    return null;
  };

  return (
    <div className={`space-y-6 max-w-7xl mx-auto pb-20 transition-all duration-[3000ms] ${isAmbientMode ? 'bg-indigo-950/20 rounded-[4rem] p-8 backdrop-blur-3xl' : ''}`}>
